        if not motion_node: continue
        table = motion_node.get('table', {})
        rows = table.get('rows', [])
        motion = {}
        for row in rows:
            frame = int(row[0])
            obj_id = row[1].split()[0]
            pos = (float(row[2]), float(row[3]))
            motion.setdefault(obj_id, []).append((frame, pos))
        # find collision events
